"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[680],{4308:(e,o,r)=>{r.d(o,{FadeIn:()=>c});var a=r(9424),n=r(3740),i=r(4753),s=r(9004),t=r(2109);let l={up:{y:1,x:0},down:{y:-1,x:0},left:{x:1,y:0},right:{x:-1,y:0},none:{x:0,y:0}};function c(e){let{children:o,className:r,direction:c="up",distance:d=30,delay:u=0,once:h=!0}=e,m=(0,n.I)(),p=l[c],[g,y]=(0,s.useState)(!1);return((0,s.useEffect)(()=>y(!0),[]),!g||m)?(0,a.jsx)("div",{className:(0,t.cn)(r),children:o}):(0,a.jsx)(i.P.div,{initial:{opacity:0,x:p.x*d,y:p.y*d},whileInView:{opacity:1,x:0,y:0},viewport:{once:h,margin:"-80px"},transition:{type:"spring",damping:25,stiffness:120,delay:u},className:(0,t.cn)(r),children:o})}},9661:(e,o,r)=>{r.d(o,{AM:()=>m,Ky:()=>f,Qe:()=>g,V3:()=>p,XT:()=>w,YX:()=>A,mG:()=>y,sF:()=>h});var a=r(8784),n=r(2712),i=r(2104),s=r(4543),t=r(3596),l=r(8421),c=r(6310),d=r(2659),u=r(1347);let h={hero:{h1Lead:"Arizona homeowners insurance that covers",h1Highlight:"the heat, the monsoon, and the wildfire",subcopy:"Dwelling coverage, personal property, liability, loss of use, flood, and umbrella — purpose-built for Arizona homeowners. We compare 12+ A-rated carriers to find the best rate for your Phoenix, Scottsdale, Tucson, or northern Arizona home. Licensed in Arizona. 15-minute quotes.",statValue:"Arizona homeowners",statLabel:"Insured across Phoenix, Scottsdale, Tucson, Chandler, and northern Arizona",imageAlt:"Arizona home in the Sonoran desert — homeowners insurance for Phoenix, Scottsdale, and Tucson"},nav:{ariaLabel:"AZ Homeowners Insurance home"},footer:{ctaTitle:"Ready to protect your Arizona home?",ctaSubcopy:"15-minute quotes. Same-day claims contact. Homeowners insurance across Arizona — Phoenix, Scottsdale, Tucson, Chandler, Flagstaff, and beyond.",description:"Arizona homeowners insurance specialists — dwelling coverage, personal property, liability, loss of use, flood, and umbrella for AZ homeowners. We compare top-rated carriers to find the best rate for your Arizona home. A division of Contractors Choice Agency — founded 2005, licensed in Arizona."},servicesGrid:{h2Lead:"Coverage built specifically for",h2Highlight:"Arizona homeowners",lead:"Arizona's homeowners insurance market is unique — extreme heat, monsoon flooding, wildfire interface risk, and carriers that have tightened underwriting across the state. We build programs designed for the actual risk of owning a home in Arizona."},why:{eyebrow:"Why Arizona homeowners switch to us",h2Lead:"The coverage gaps that",h2Highlight:"cost Arizona homeowners the most",lead:"Most homeowners don't find out their coverage is wrong until a claim is denied. We check your dwelling rebuild cost, your flood exclusion, your liability limits for pools and dogs, and your personal property sub-limits before you need them.",sidebarTitle:"Local Arizona expertise since 2005",sidebarBody:"Contractors Choice Agency was founded in Chandler, AZ in 2005. We know Arizona's homeowners market — monsoon season claims patterns, wildfire interface underwriting, and which carriers actually pay fairly in the Valley."},coverage:{eyebrow:"Where we write",h2Lead:"Arizona homeowners insurance.",h2Highlight:"Phoenix to Flagstaff.",lead:"From the Phoenix metro and Scottsdale to Tucson, Prescott, and northern Arizona, we insure Arizona homes across every region and risk profile.",imageAlt:"Arizona neighborhood with desert landscaping — homeowners insurance coverage across Phoenix, Tucson, and Flagstaff",badgeTitle:"Statewide coverage for Arizona homeowners.",badgeSub:"Insuring Arizona homes since 2005."},process:{lead:"No forms that take an hour, no callbacks from a call center. Tell us about your Arizona home, we shop the right carriers, and you have real quotes in 15 minutes — not a week."},finalCta:{h2Lead:"Protect Your Arizona Home",h2Highlight:"with coverage built for the desert.",lead:"Whether you need a standard HO-3 policy today, or a full program — dwelling, flood, umbrella, scheduled property — one call gets you real quotes from carriers that understand Arizona's risk environment. Not a voicemail and a two-week wait."},ctaBand:{defaultTitle:"Ready to protect your Arizona home?",defaultDescription:"Get a 15-minute quote from specialists who understand Arizona homeowners insurance — monsoon flood risk, wildfire interface underwriting, pool liability, and dwelling rebuild costs in Arizona's construction market."},faq:{defaultTitleLead:"Arizona homeowners insurance,",defaultTitleHighlight:"in plain English"},servicesPage:{metaTitle:"Arizona Homeowners Insurance Coverage & Services | AZ Home Insurance",metaDescription:"Twelve lines of homeowners insurance for Arizona — dwelling, personal property, liability, loss of use, flood, umbrella, scheduled property, rental, condo, renters, mobile home, and high-value home coverage. Licensed in Arizona, quotes in 15 minutes.",h1Lead:"Insurance built line-by-line for",h1Highlight:"Arizona homeowners",lead:"Each coverage below addresses a specific exposure Arizona homeowners face — from monsoon flooding standard policies exclude to wildfire interface dwelling coverage and pool liability.",ogTitle:"Arizona Homeowners Insurance Coverage | AZ Homeowners Insurance",ogDescription:"Dwelling, personal property, liability, loss of use, flood, umbrella, scheduled property, and rental coverage for Arizona homeowners. Licensed in Arizona, quotes in 15 minutes.",ctaTitle:"Not sure which coverage you need?",ctaDescription:"Most Arizona homeowners need dwelling, personal property, liability, and loss of use at minimum — plus flood if you're in a monsoon-prone area. We'll build the right program in one call."},blogPage:{metaTitle:"Arizona Homeowners Insurance Blog — Guides & Insights",metaDescription:"Practical homeowners insurance guidance for Arizona — monsoon flood coverage, wildfire interface underwriting, pool liability, dwelling rebuild cost, and choosing the right AZ home insurance policy.",h1Lead:"Arizona homeowners insurance,",h1Highlight:"decoded",lead:"Plain-English guides on the coverage that matters for Arizona homeowners — monsoon flooding, wildfire risk, pool liability, dwelling rebuild cost, and how to stop overpaying on renewal.",ogTitle:"Arizona Homeowners Insurance Blog | AZ Homeowners Insurance",ogDescription:"Practical homeowners insurance guidance for Arizona — monsoon flood coverage, wildfire interface underwriting, pool liability, dwelling rebuild cost, and choosing the right AZ home insurance policy."},serviceDetail:{h1Suffix:"for Arizona homeowners",imageAltSuffix:"Arizona homeowners insurance",category:"Arizona Homeowners Insurance"},about:{metaTitle:"About AZ Homeowners Insurance | Contractors Choice Agency",metaDescription:"AZ Homeowners Insurance is the Arizona home-focused division of Contractors Choice Agency, founded in 2005 in Chandler, AZ. Dwelling, flood, liability, and umbrella coverage for Arizona homeowners. Licensed in Arizona.",h1Lead:"Built by Arizona insurance professionals,",h1Highlight:"for Arizona homeowners",lead:"AZ Homeowners Insurance is the Arizona home-focused division of Contractors Choice Agency — founded in 2005 by Josh Cotner in Chandler, AZ. We know Arizona's homeowners market because we've been in it for 20 years.",imageAlt:"Arizona home with desert landscaping — insured by AZ Homeowners Insurance, a division of Contractors Choice Agency",storyEyebrow:"Our story",storyTitle:"Founded in Arizona. Built for Arizona homes.",storyLead:"Josh Cotner founded Contractors Choice Agency in Chandler in 2005. Over 20 years we've seen every challenge Arizona homeowners face — monsoon claims, wildfire interface underwriting, carriers exiting the state, and the coverage gaps that show up at claim time.",valuesTitle:"Four things we won't compromise on.",timeline:[{year:"2005",title:"Contractors Choice Agency founded in Chandler, AZ",desc:"Josh Cotner opens CCA in Chandler — built to provide honest, expert insurance guidance for Arizona businesses and homeowners."},{year:"10 yrs",title:"Expanded Arizona homeowners division",desc:"CCA builds a dedicated homeowners division focused on AZ-specific risk: monsoon, wildfire, extreme heat, and specialty coverage needs."},{year:"Today",title:"AZ Homeowners Insurance — statewide coverage",desc:"Serving Phoenix, Scottsdale, Tucson, Chandler, Flagstaff, Prescott, and every Arizona market — with 12+ carriers compared for every quote."}],values:[{icon:"Home",title:"Arizona-first expertise",desc:"We know Arizona's homeowners market — monsoon season claims, wildfire interface underwriting, carriers tightening in the Valley, and the rebuild-cost gaps that leave homeowners underinsured."},{icon:"ShieldCheck",title:"Coverage that closes the gaps",desc:"Flood exclusions in standard policies, pool liability, dwelling underinsurance, personal property sub-limits — we check all of it before you need it."},{icon:"Award",title:"A-rated carriers only",desc:"We shop 12+ carriers with strong financial ratings and fair claims handling — so when a monsoon event or wildfire hits, your claim gets paid."},{icon:"Handshake",title:"Honest, no-pressure advice",desc:"If you don't need a coverage line, we'll tell you. We earn long-term clients by being straight about what your Arizona home actually requires."}]},quote:{h1Lead:"Get your",h1Highlight:"Arizona homeowners insurance quote",lead:"Tell us about your Arizona home. We'll shop 12+ A-rated carriers and come back with real quotes in about 15 minutes — no obligation.",businessPlaceholder:"Property street address, city, ZIP",emailPlaceholder:"yourname@email.com",phonePlaceholder:"(480) 555-0100",messagePlaceholder:"Home address, year built, square footage, construction type, pool/trampoline/dogs, current insurer, renewal date, or anything else that helps us quote accurately…",errorMessage:"Something went wrong. Please call us at 844-967-5247 or try again.",trustNicheTitle:"Built for Arizona homeowners",trustNicheDesc:"Policies written for Arizona's climate — not generic home coverage."},contact:{h1Lead:"Let's talk about your",h1Highlight:"Arizona homeowners coverage",lead:"Questions, a quote, or a claim — reach a person who knows Arizona's homeowners market, not a call center.",errorMessage:"Something went wrong. Please call us at 844-967-5247."},coveragePage:{metaTitle:"Arizona Homeowners Insurance — Phoenix, Scottsdale, Tucson & Statewide",metaDescription:"AZ Homeowners Insurance writes homeowners insurance across Arizona — Phoenix, Scottsdale, Tucson, Chandler, Flagstaff, Prescott, and every Arizona market. Licensed in Arizona, quotes in 15 minutes.",h1Lead:"Arizona statewide coverage.",h1Highlight:"Phoenix to Flagstaff, every AZ market.",lead:"We insure Arizona homes across every region — Phoenix metro, Scottsdale, Tucson, the East Valley, northern Arizona, and Prescott/Yavapai County.",sectionTitle:"Arizona regions we serve.",statewideLead:"Whether your home is in the Phoenix metro, Tucson, Flagstaff, or a small Arizona community, we compare carriers to find the right coverage. NPN #8608479.",faqs:[{q:"Do you only write homeowners insurance in certain parts of Arizona?",a:"No. We insure homes across all of Arizona — Phoenix metro, Scottsdale, Tucson, Chandler, Gilbert, Tempe, Flagstaff, Prescott, Sedona, Sierra Vista, and everywhere in between."},{q:"Can you insure a high-value home in Scottsdale or Paradise Valley?",a:"Yes. We access specialty markets for high-value Arizona homes that require true replacement-cost coverage above $1M. Scottsdale and Paradise Valley homes often need carriers with custom rebuild-cost analysis and extended replacement-cost endorsements."},{q:"Can you insure a home in a wildfire interface area like Flagstaff or Prescott?",a:"Yes — though the market is challenging. We work with admitted and surplus lines carriers that still write WUI (wildland-urban interface) homes in Flagstaff, Prescott, Sedona, and other northern Arizona communities where some carriers have exited."},{q:"Do you write rental properties and investment homes in Arizona?",a:"Yes. We write landlord policies and dwelling fire policies for Arizona rental properties, vacation homes, and vacant properties — including Phoenix, Scottsdale, and Tucson investment homes."}]}},m=[{step:"01",icon:a.A,title:"Tell us about your Arizona home",description:"15-min call or quick form. Home address, year built, square footage, pool or dogs, current insurer, and what's changed since your last renewal."},{step:"02",icon:n.A,title:"We shop 12+ Arizona carriers",description:"We compare rates and coverage from multiple A-rated carriers that write in Arizona — including options your current agent may not have access to."},{step:"03",icon:i.A,title:"Bind a policy built for your home",description:"Dwelling + personal property + liability + loss of use, plus flood or umbrella if needed — one coordinated program with no coverage gaps."},{step:"04",icon:s.A,title:"Claims support when you need it",description:"When a monsoon event, wildfire, theft, or liability claim arrives, you reach a person who knows your policy — not a call center. Same-day contact."}],p=[{icon:s.A,title:"Dwelling coverage at true rebuild cost",description:"Many Arizona homeowners are insured at market value — not replacement cost. After a total loss, you need to rebuild, not buy. We verify your dwelling limit against actual construction costs in your Arizona market."},{icon:t.A,title:"Flood coverage for monsoon season",description:"Standard homeowners policies exclude flood entirely. Arizona's monsoon season brings flash flooding that can cause tens of thousands in damage — we add NFIP or private flood coverage so you're not uncovered."},{icon:l.A,title:"12+ carriers compared for every quote",description:"We don't work for one carrier. We compare 12+ A-rated options for your Arizona home and present the best combination of price, coverage, and financial strength."},{icon:c.A,title:"Scheduled property for high-value items",description:"Jewelry, firearms, art, and collections have low sub-limits under standard policies. We schedule individual items to ensure they're covered for their actual replacement value."},{icon:d.A,title:"Umbrella for pool and dog liability",description:"Arizona pools and dog bites are among the leading sources of personal liability claims. A $1M umbrella above your base liability limits covers the gap between your policy and a serious injury judgment."},{icon:u.A,title:"Rental property and vacant home coverage",description:"Standard HO-3 policies don't cover non-owner-occupied or vacant properties. We write landlord policies and dwelling fire policies for Arizona rental properties and investment homes."}],g=[{q:"What does homeowners insurance cover in Arizona?",a:"A standard Arizona homeowners policy (HO-3) covers your dwelling structure, personal property, personal liability, and loss of use if your home is uninhabitable after a covered loss. It does NOT cover flood, earthquake, or normal wear and tear. Arizona homeowners in monsoon zones should strongly consider adding flood coverage separately."},{q:"How much does homeowners insurance cost in Arizona?",a:"Arizona homeowners insurance averages $1,200–$2,500/year depending on location, home value, age, construction type, wildfire risk, flood zone, pool, dogs, and claims history. Phoenix and Tucson metro homes tend to run lower; northern Arizona and wildfire interface areas run significantly higher. We compare 12+ carriers to find your best rate."},{q:"Does homeowners insurance cover monsoon damage in Arizona?",a:"Yes — windstorm and hail from monsoon storms are covered under a standard HO-3. However, flood from monsoon runoff or flash flooding is excluded under the flood exclusion. You need separate flood coverage (NFIP or private flood) to cover monsoon-related flooding."},{q:"Does homeowners insurance cover wildfire damage in Arizona?",a:"Yes. Wildfire is a covered peril under standard Arizona homeowners policies. However, some carriers have restricted underwriting in wildfire interface (WUI) zones — particularly around Flagstaff, Prescott, and Sedona. If you're in a WUI area, we access specialty carriers that still write competitively in those markets."},{q:"What is not covered by Arizona homeowners insurance?",a:"Standard Arizona homeowners policies exclude flood, earthquake, sewer backup (unless endorsed), normal wear and tear, pest damage, and intentional acts. Luxury items like jewelry, firearms, and art often have sub-limits. We review your exclusions and fill the gaps with endorsements or separate policies."},{q:"Do I need flood insurance in Arizona?",a:"If you're in a FEMA-designated flood zone, your lender will require it. But flash flooding from Arizona monsoons can affect homes well outside mapped flood zones. We recommend flood coverage for any Arizona home in a low-lying area, near a wash, or in a known monsoon runoff corridor."},{q:"How much dwelling coverage do I need for my Arizona home?",a:"You need enough to rebuild your home at current Arizona construction costs — not its market value. In Arizona, residential reconstruction runs $150–$350+ per square foot depending on construction type, finishes, and location. Many Arizona homeowners are underinsured because their policy was set at purchase price, not rebuild cost. We verify this for every client."},{q:"Does homeowners insurance cover my pool in Arizona?",a:"Your pool structure is covered under dwelling coverage. Pool equipment (pumps, heaters) may be covered under personal property or other structures. Pool-related liability — if a guest is injured in your pool — is covered under your personal liability limit. A pool increases your liability exposure; we often recommend an umbrella policy."},{q:"Does homeowners insurance cover dog bites in Arizona?",a:"Yes, under your personal liability coverage. Arizona has strict liability laws for dog bites — owners are liable regardless of the dog's history. If you own a large-breed dog or a breed some carriers surcharge or exclude, we find you carriers that write the coverage without restricting your dog."},{q:"What is loss of use coverage and why is it important in Arizona?",a:"Loss of use (additional living expenses) pays for hotel, food, and temporary housing if a covered loss makes your Arizona home uninhabitable during repairs. In the Phoenix metro, hotel rates run $150–$400/night. A major claim repair can take months — loss of use coverage is critical."},{q:"Can I get homeowners insurance for a high-value home in Scottsdale?",a:"Yes. We access specialty markets for high-value Scottsdale, Paradise Valley, and Fountain Hills homes that require true replacement-cost coverage, extended replacement-cost endorsements, and custom rebuild-cost analysis. Standard carriers often underprice and underinsure these properties."},{q:"What does an umbrella policy cover in addition to homeowners insurance?",a:"A personal umbrella adds $1M–$5M in liability above your homeowners and auto policies. It pays when a judgment exceeds your base liability limit — from a pool injury, dog bite, serious auto accident, or other liability event."},{q:"How do I insure a rental property or investment home in Arizona?",a:"Standard HO-3 policies cover owner-occupied homes only. For rental properties, you need a landlord policy (also called a dwelling fire or DP-3 policy) that covers the structure, your liability as a landlord, and optional loss of rents. We write landlord policies for Phoenix, Scottsdale, Tucson, and East Valley rental properties."},{q:"What is scheduled personal property and when do I need it?",a:"Standard homeowners policies cap jewelry, firearms, and fine art at low sub-limits. If your jewelry, gun collection, art, or other valuables exceed those sub-limits, you need to schedule individual items. Scheduled coverage removes sub-limits and often covers mysterious disappearance."},{q:"Can you insure a home in a wildfire interface area near Flagstaff or Prescott?",a:"Yes — though it's challenging. Some admitted carriers have exited northern Arizona WUI zones. We work with specialty admitted and surplus lines markets that still write Flagstaff, Prescott, Sedona, and Yavapai County homes with competitive terms."},{q:"Does homeowners insurance cover my personal property outside my home?",a:"Yes. Standard HO-3 policies cover your personal property worldwide at a reduced percentage (typically 10% of your personal property limit). If your laptop is stolen from your car or your luggage is lost on a trip, your homeowners policy may cover it."},{q:"What happens if my Arizona home is vacant?",a:"A standard HO-3 typically excludes or limits coverage after 30–60 days of vacancy. If your Arizona home is vacant for an extended period — during renovation, estate settlement, or a seasonal absence — you need a vacancy endorsement or a separate dwelling fire policy to maintain coverage."},{q:"How do I reduce my Arizona homeowners insurance premium?",a:"The most effective ways: install a monitored alarm system (5–15% discount), add impact-resistant roofing (10–30%), bundle with your auto policy (5–15%), increase your deductible, and shop multiple carriers at renewal. We re-shop your coverage annually to prevent renewal-creep premium increases."},{q:"Does homeowners insurance cover sewer backup in Arizona?",a:"Not by default. Sewer and drain backup is excluded from standard HO-3 policies but can be added as an endorsement for $50–$150/year. Given Arizona's aging sewer infrastructure in older Phoenix and Tucson neighborhoods, it's a cost-effective add."},{q:"How do I file a homeowners insurance claim in Arizona?",a:"Contact your insurer directly (their claims line is on your declarations page) as soon as the loss occurs. Document everything with photos before making temporary repairs. Temporary repairs to prevent further damage are covered — keep receipts. We walk clients through the process and help navigate disputes with the carrier."}],y=[{name:"Phoenix Metro",cities:"Phoenix \xb7 Mesa \xb7 Tempe \xb7 Glendale \xb7 Peoria",description:"The largest Arizona homeowners market. We compare 12+ carriers for Phoenix metro homes and re-shop annually to prevent renewal-creep."},{name:"Scottsdale & East Valley",cities:"Scottsdale \xb7 Paradise Valley \xb7 Chandler \xb7 Gilbert \xb7 Queen Creek",description:"High-value homes and newer subdivisions. Specialty markets for Scottsdale custom homes; competitive programs for East Valley families."},{name:"Tucson & Southern Arizona",cities:"Tucson \xb7 Marana \xb7 Oro Valley \xb7 Sierra Vista \xb7 Nogales",description:"Arizona's second-largest market. Competitive homeowners programs for Tucson homes across all ages, conditions, and risk profiles."},{name:"Northern Arizona",cities:"Flagstaff \xb7 Sedona \xb7 Williams \xb7 Winslow \xb7 Show Low",description:"WUI specialist access for Flagstaff and northern Arizona homes. Admitted and surplus lines options when standard carriers decline."},{name:"Prescott & Yavapai County",cities:"Prescott \xb7 Prescott Valley \xb7 Chino Valley \xb7 Cottonwood",description:"Challenging market requiring specialty placement. We work all admitted and surplus lines options for Prescott-area homeowners."},{name:"West & Northwest Arizona",cities:"Surprise \xb7 Buckeye \xb7 Goodyear \xb7 Avondale \xb7 Wickenburg",description:"Newer West Valley communities with favorable risk profiles. Competitive programs for growing West Valley homeowners."}],f=["Arizona"],w=["Homeowners Insurance (HO-3)","Condo Insurance (HO-6)","Renters Insurance (HO-4)","Flood Insurance","Personal Umbrella","Rental / Landlord Policy","Vacant Home Coverage","Scheduled Personal Property","Bundle (Home + Auto)","Other / Not Sure"],A=["Just purchased","1–2 years","3–5 years","6–10 years","10+ years"]}}]);